<script setup>
import {ref,computed,onBeforeUnmount} from 'vue';
import {parseSrt,analyze,report} from './core.js';
const source=ref(''),cues=ref([]),notes=ref({}),selected=ref(0),error=ref(''),status=ref('Open a basic UTF-8 SRT file or try the fictional demo.');
const cps=ref(20),line=ref(42),min=ref(1),onlyFlags=ref(false),videoUrl=ref(''),video=ref(null),loop=ref(false),time=ref(0),exportUrl=ref(''),confirmExport=ref(false);
const thresholds=computed(()=>({cps:Number(cps.value),line:Number(line.value),min:Number(min.value)}));
const measured=computed(()=>{try{return analyze(cues.value,thresholds.value);}catch{return [];}});
const active=computed(()=>measured.value[selected.value]);
const filtered=computed(()=>measured.value.filter(c=>!onlyFlags.value||c.flags.length));
const reviewed=computed(()=>Object.values(notes.value).filter(n=>n.state!=='unreviewed').length);
function revokeExport(){if(exportUrl.value)status.value='Review changed. Build a new report when ready.';if(exportUrl.value)URL.revokeObjectURL(exportUrl.value);exportUrl.value='';confirmExport.value=false;}
function inspect(){error.value='';revokeExport();try{const next=parseSrt(source.value);analyze(next,thresholds.value);cues.value=next;notes.value=Object.fromEntries(next.map(c=>[c.ordinal,{state:'unreviewed',note:''}]));selected.value=0;loop.value=false;status.value=`${next.length} cues loaded. Review notes exist only in this tab.`;}catch(e){cues.value=[];notes.value={};error.value=e.message;}}
async function loadSrt(e){const f=e.target.files[0];if(!f)return;try{if(f.size>2*1024*1024)throw Error('SRT must be at most 2 MiB.');source.value=new TextDecoder('utf-8',{fatal:true}).decode(await f.arrayBuffer());inspect();}catch{error.value='Could not read this file as a bounded UTF-8 SRT. Existing review is unchanged.';}finally{e.target.value='';}}
function demo(){source.value='1\n00:00:01,000 --> 00:00:03,000\nWelcome to the fictional subtitle demo.\n\n2\n00:00:03,100 --> 00:00:03,700\nThis deliberately crowded line is much too quick to read comfortably.\n\n3\n00:00:03,500 --> 00:00:06,000\nA cue overlapping the previous cue.\n\n4\n00:00:07,000 --> 00:00:10,000\nA quiet ending.\n';inspect();}
function choose(index){selected.value=index;loop.value=false;if(video.value&&videoUrl.value){try{video.value.currentTime=measured.value[index].start/1000;}catch{error.value='Video is not ready for seeking.';}}}
function playback(){if(!video.value||!active.value)return;loop.value=true;video.value.currentTime=active.value.start/1000;video.value.play().catch(()=>{loop.value=false;error.value='Playback did not start. Use the video controls or a supported media file.';});}
function track(){time.value=video.value?.currentTime||0;if(loop.value&&active.value&&time.value>=active.value.end/1000){video.value.pause();loop.value=false;}}
function loadVideo(e){const f=e.target.files[0];if(!f)return;if(videoUrl.value)URL.revokeObjectURL(videoUrl.value);videoUrl.value=URL.createObjectURL(f);loop.value=false;status.value='Local video loaded. It is not uploaded. Codec support depends on your browser.';e.target.value='';}
function clear(){video.value?.pause();if(videoUrl.value)URL.revokeObjectURL(videoUrl.value);videoUrl.value='';source.value='';cues.value=[];notes.value={};revokeExport();error.value='';status.value='Page review cleared. Downloaded reports and original files are not deleted.';}
function exportReport(){revokeExport();try{analyze(cues.value,thresholds.value);exportUrl.value=URL.createObjectURL(new Blob([JSON.stringify(report(measured.value,notes.value,thresholds.value),null,2)],{type:'application/json'}));status.value='Report ready. Captions are omitted, but your notes and cue times are included.';}catch(e){error.value=e.message;}}
function settingsChanged(){revokeExport();try{analyze(cues.value,thresholds.value);error.value='';}catch(e){error.value=e.message;}}
onBeforeUnmount(clear);
</script>
<template>
<div class="shell"><header><div class="brand"><svg width="44" height="44" viewBox="0 0 48 48" role="img" aria-label="N inside a subtitle frame"><rect width="48" height="48" rx="13" fill="#f3b86c"/><rect x="7" y="11" width="34" height="26" rx="3" fill="none" stroke="#372a24" stroke-width="2"/><path d="M15 31V17h4l10 9V17h4v14h-4l-10-9v9z" fill="#372a24"/></svg><div>CueDesk<small>LOCAL SUBTITLE REVIEW / VUE</small></div></div><span>NO UPLOADS · NO ACCOUNT</span></header>
<main><section class="intro"><p class="eyebrow">READ THE CUE. CHECK THE MOMENT.</p><h1>Make subtitle review<br/>a deliberate pass.</h1><p>A local SRT review desk with cue navigation, optional video and notes. Reading-load flags help you choose what to inspect. They do not approve your subtitles.</p></section>
<section class="inputbar"><label class="filebutton">Open SRT<input type="file" accept=".srt,text/plain" aria-label="Open UTF-8 SRT" @change="loadSrt"/></label><label class="filebutton secondary">Optional local video<input type="file" accept="video/*" aria-label="Open local video" @change="loadVideo"/></label><button @click="demo">Fictional demo</button><button class="quiet" @click="clear">Clear review</button><span>{{cues.length}} cues · {{reviewed}} reviewed</span></section>
<p class="status" role="status">{{status}}</p><p v-if="error" class="error" role="alert">{{error}}</p>
<details><summary>Or paste basic SRT</summary><textarea v-model="source" aria-label="SRT text" maxlength="2097152" spellcheck="false"></textarea><button @click="inspect">Start a new review</button><p>Starting again replaces the current in-tab notes. Nothing is saved automatically.</p></details>
<div class="workspace"><section class="cuepanel"><div class="panelhead"><h2>01 / Cue list</h2><label><input type="checkbox" v-model="onlyFlags"/> Flags only</label></div><div class="cuelist"><button v-for="c in filtered" :key="c.ordinal" class="cue" :class="{selected:active?.ordinal===c.ordinal}" @click="choose(c.ordinal-1)"><span class="cuenum">{{String(c.ordinal).padStart(3,'0')}}</span><span class="cuebody"><strong>{{c.text}}</strong><small>{{(c.start/1000).toFixed(3)}}s → {{(c.end/1000).toFixed(3)}}s · {{c.cps.toFixed(1)}} chars/s · {{notes[c.ordinal]?.state}}</small><em v-if="c.flags.length">{{c.flags.join(' · ')}}</em></span></button><p v-if="!filtered.length" class="empty">{{cues.length?'No cues match this filter.':'Your cues will appear here.'}}</p></div></section>
<section class="reviewpanel"><div class="panelhead"><h2>02 / Inspect & annotate</h2><span>{{active ? `Cue ${active.ordinal}`:'No cue selected'}}</span></div><video v-if="videoUrl" ref="video" :src="videoUrl" controls preload="metadata" @timeupdate="track" @error="error='This browser could not play the video. Try a supported codec or review without video.'"></video><div v-else class="novideo">Video is optional.<small>Use your own player, or open a local video here to seek and play a selected cue. No subtitles are burned into the video.</small></div><template v-if="active"><div class="caption" dir="auto">{{active.text}}</div><div class="metrics"><span>{{active.duration.toFixed(3)}}<small>SECONDS</small></span><span>{{active.count}}<small>GRAPHEMES</small></span><span>{{active.cps.toFixed(1)}}<small>PER SECOND</small></span></div><div class="nav"><button :disabled="selected===0" @click="choose(selected-1)">Previous</button><button :disabled="!videoUrl" @click="playback">Play this cue</button><button :disabled="selected>=cues.length-1" @click="choose(selected+1)">Next</button></div><p class="fine">Cue playback stops approximately at its end using browser time updates, not frame-accurate control. This is not a loop or automatic sync check.</p><label class="field">Review decision<select v-model="notes[active.ordinal].state" @change="revokeExport"><option value="unreviewed">Unreviewed</option><option value="keep">Keep after review</option><option value="revisit">Revisit</option></select></label><label class="field">Your note<textarea v-model="notes[active.ordinal].note" maxlength="2000" @input="revokeExport" placeholder="What should be checked in the subtitle editor?"/></label></template></section></div>
<section class="settings"><div><h2>03 / Review thresholds</h2><p>These editable starting values are examples, not a delivery profile. Grapheme clusters are counted with spaces and punctuation, without line breaks. Markup is counted literally and flagged.</p></div><label>Max chars / second<input type="number" v-model="cps" min="1" max="100" @input="settingsChanged"/></label><label>Max chars / line<input type="number" v-model="line" min="1" max="200" @input="settingsChanged"/></label><label>Min seconds<input type="number" v-model="min" min="0" max="30" step="0.1" @input="settingsChanged"/></label></section>
<section class="export"><div><h2>04 / Take your review with you</h2><p>JSON report includes cue positions, timing, metrics, decisions and your notes. No source filename, cue ID or caption text. Your notes may still contain private data.</p></div><button :disabled="!cues.length||!measured.length" @click="exportReport">Build review report</button><template v-if="exportUrl"><label><input type="checkbox" v-model="confirmExport"/> I checked my notes and timing before sharing.</label><a v-if="confirmExport" :href="exportUrl" download="cuedesk-review.json">Download JSON review</a></template></section>
<section class="limits"><h2>A review aid, not a verdict.</h2><p>Basic UTF-8 SRT only, at most 2 MiB and 5,000 cues. No WebVTT, ASS, styling interpretation, translation, repair, speech analysis, synchronization certification or subtitle editing. A quiet flag list does not prove accessibility, accuracy or readiness. No browser storage; clearing or reloading loses notes. Review data stays in this tab until cleared/closed. Browser codecs determine whether local video can play.</p></section></main><footer>Built by Nelli · MIT licensed · Vue runtime included with its license · No analytics or external runtime requests.</footer></div>
</template>
<style>
*{box-sizing:border-box}body{margin:0;background:#f5f1e9;color:#302c29;font:15px/1.55 Arial,Helvetica,sans-serif}button,.filebutton,a{font:inherit;font-weight:600;cursor:pointer;border:1px solid #786859;background:#473c32;color:#fff9ed;border-radius:8px;padding:10px 15px;text-decoration:none;display:inline-block}button:disabled{opacity:.4;cursor:not-allowed}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,a:focus-visible{outline:3px solid #bd591e;outline-offset:3px}.shell{max-width:1400px;margin:auto;padding:28px 40px}header{display:flex;justify-content:space-between;align-items:center;padding-bottom:24px;border-bottom:1px solid #d6cbba}.brand{display:flex;gap:12px;align-items:center;font-size:23px;font-weight:bold}.brand small{display:block;font-size:9px;letter-spacing:1.5px;color:#827361}header>span{font-size:10px;letter-spacing:1.5px;color:#8a5a2c}.intro{display:grid;grid-template-columns:1.2fr 1fr;gap:8px 70px;padding:35px 0}.eyebrow{grid-column:1/-1;color:#aa582c;font-size:10px;letter-spacing:2px;font-weight:bold}h1{font-size:clamp(32px,3.8vw,52px);line-height:1.12;letter-spacing:-1.5px;margin:0}.intro>p:last-child{align-self:end;color:#766854;font-size:16px;margin:0}h2{font-size:17px;margin:0 0 10px}p{margin:0 0 15px}.inputbar{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.inputbar>span{margin-left:auto;color:#7c6d5c;font-size:12px}.filebutton{position:relative;overflow:hidden;background:#a0522b;border-color:#a0522b}.filebutton input{position:absolute;inset:0;opacity:0;width:100%;cursor:pointer}.secondary,.quiet{background:transparent;color:#514334}.status{margin:16px 0;background:#e8dfd0;padding:10px 14px;border-radius:7px;font-size:12px}.error{background:#f7d9ce;color:#8e2f14;padding:14px;border-radius:7px}details{margin:12px 0 22px;font-size:12px;color:#776550}summary{cursor:pointer}details textarea{display:block;width:100%;height:120px;margin:10px 0}.workspace{display:grid;grid-template-columns:1fr 1fr;gap:22px}.cuepanel,.reviewpanel{background:#fffdf7;border:1px solid #dacebc;border-radius:14px;overflow:hidden}.panelhead{display:flex;align-items:center;justify-content:space-between;padding:18px 20px;border-bottom:1px solid #e6ddce}.panelhead h2{margin:0}.panelhead label,.panelhead span{font-size:11px;color:#8a755c}.cuelist{max-height:650px;overflow:auto}.cue{display:flex;gap:15px;border:0;border-bottom:1px solid #e6ddce;border-radius:0;background:transparent;color:#4a4035;width:100%;text-align:left;padding:18px;font-weight:400}.cue.selected{background:#f7e5cb;box-shadow:inset 4px 0 #a0522b}.cuenum{font-size:12px;color:#a27c50;font-variant-numeric:tabular-nums}.cuebody{min-width:0}.cuebody strong{display:block;white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px;font-weight:500}.cuebody small{display:block;color:#8c7963;font-size:10px;margin-top:8px}.cuebody em{display:block;color:#a64c20;font-style:normal;font-size:10px;margin-top:8px}.empty{padding:35px;color:#95816a}.reviewpanel{padding-bottom:20px}video{width:100%;max-height:320px;background:#191512;display:block}.novideo{padding:28px 22px;background:#ede8df;color:#7c6a56}.novideo small{display:block;margin-top:8px;font-size:12px}.caption{margin:20px;background:#312c27;color:#fff7e8;border-radius:9px;padding:25px 20px;white-space:pre-wrap;text-align:center;font-size:19px;overflow-wrap:anywhere}.metrics{display:flex;gap:35px;padding:0 22px}.metrics>span{font-size:24px;font-variant-numeric:tabular-nums}.metrics small{display:block;font-size:8px;letter-spacing:1px;color:#9a7e5c}.nav{display:flex;gap:8px;padding:18px 20px 10px;flex-wrap:wrap}.nav button{font-size:12px;padding:8px 12px}.fine{font-size:10px;color:#8e775c;margin:0 20px 16px}.field{display:block;font-size:12px;color:#7f674d;margin:12px 20px}.field select,.field textarea{display:block;width:100%;margin-top:6px}input,textarea,select{font:inherit;padding:9px;background:#fffdf7;border:1px solid #cbb99e;border-radius:6px;color:#403425}textarea{resize:vertical;min-height:80px}.settings{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:22px;background:#e7dece;border-radius:12px;padding:23px;margin-top:24px}.settings p,.export p{font-size:12px;color:#7e6a50;margin:0}.settings label{font-size:11px;align-self:center;color:#7f674b}.settings input{display:block;width:100%;margin-top:8px}.export{padding:25px 0;display:flex;align-items:center;gap:25px;flex-wrap:wrap}.export>div{flex:1;min-width:250px}.export>label{font-size:12px}.export a{background:#a0522b}.limits{border-top:1px solid #d6cbba;padding:24px 0;max-width:950px}.limits p{font-size:11px;color:#897359}footer{font-size:10px;color:#a18461;border-top:1px solid #d6cbba;padding-top:20px}@media(max-width:760px){.shell{padding:20px}.intro{grid-template-columns:1fr;gap:20px}header>span{display:none}.workspace{grid-template-columns:1fr}.settings{grid-template-columns:1fr 1fr}.settings>div{grid-column:1/-1}.inputbar>span{width:100%;margin:5px 0}.intro>p:last-child{font-size:14px}.metrics{gap:25px}.export{gap:15px}.cuelist{max-height:380px}}
</style>
